function IdolLive3D_RoleIKMgr:__init( mainForRuntime_, roleTF_ )

    self.mainForRuntime = mainForRuntime_
    self.interactiveManagerEnv = nil -- delay 到 SelfUpdate() 中去被绑定;
    self.mainCamera = self.mainForRuntime.mainCamera
    self.uiMain = self.mainForRuntime.uiMain
    self.ikHandEnv = self.uiMain.ikHandEnv
    self.roleTF =roleTF_
    self.baseJson = mainForRuntime_.baseJson

    self.IKParamJsonList = nil -- 数组
    self.IKParamJson = nil

    --- 这两个 flag 存在功能上的 细微的差异:
    IdolLive3D_StatesV2.IsInsideIKDragSwipe = false
    IdolLive3D_StatesV2.IsIKDragging = false
    
    -- 开关:
    self.isUsed = 
    {
        Body = false,
        LeftArm = false,
        RightArm = false,
        LeftLeg = false,
        RightLeg = false,
    }


    self.fullBodyBipedIK = KTool.GetComponent(self.roleTF.gameObject, typeof(FullBodyBipedIK))
    self.isFind_FullBodyBipedIK = isNotNull(self.fullBodyBipedIK)
    if self.isFind_FullBodyBipedIK == false then 
        return
    end 
    local ikSolver = self.fullBodyBipedIK.solver

    -- 交互节点:
    self.catchedDragNode = nil
    --------------------------
    -- localPlayTimes: 每次进入新的 stage, 本值都会被重置为0; 每次被 swipe捕获, 本值会在首帧被+1, 所以 1表示第一次play; (除了它, 还存在 ikJson.totalPlayTimes)
    self.dragNodes = {} 
    self.dragNodes[IKNodeType.Spine1]       = { tf = ikSolver.bodyEffector.target,                      colliderTF = nil, ikJson = nil, localPlayTimes = 0 }   -- 腰
    --- ===
    self.dragNodes[IKNodeType.lWrist]       = { tf = ikSolver.leftHandEffector.target,                  colliderTF = nil, ikJson = nil, localPlayTimes = 0 } -- 左-手腕
    self.dragNodes[IKNodeType.lShoulder]    = { tf = ikSolver.leftShoulderEffector.target,              colliderTF = nil, ikJson = nil, localPlayTimes = 0 } -- 左-肩
    self.dragNodes[IKNodeType.lElbow]       = { tf = ikSolver.leftArmChain.bendConstraint.bendGoal,     colliderTF = nil, ikJson = nil, localPlayTimes = 0 } -- 左-肘
    ---
    self.dragNodes[IKNodeType.lAnkle]       = { tf = ikSolver.leftFootEffector.target,                  colliderTF = nil, ikJson = nil, localPlayTimes = 0 } -- 左-脚踝
    self.dragNodes[IKNodeType.lHip]         = { tf = ikSolver.leftThighEffector.target,                 colliderTF = nil, ikJson = nil, localPlayTimes = 0 } -- 左-臀
    self.dragNodes[IKNodeType.lKnee]        = { tf = ikSolver.leftLegChain.bendConstraint.bendGoal,     colliderTF = nil, ikJson = nil, localPlayTimes = 0 } -- 左-膝盖
    --- ===
    self.dragNodes[IKNodeType.rWrist]       = { tf = ikSolver.rightHandEffector.target,                 colliderTF = nil, ikJson = nil, localPlayTimes = 0 } -- 右-手腕
    self.dragNodes[IKNodeType.rShoulder]    = { tf = ikSolver.rightShoulderEffector.target,             colliderTF = nil, ikJson = nil, localPlayTimes = 0 } -- 右-肩
    self.dragNodes[IKNodeType.rElbow]       = { tf = ikSolver.rightArmChain.bendConstraint.bendGoal,    colliderTF = nil, ikJson = nil, localPlayTimes = 0 } -- 右-肘
    ---
    self.dragNodes[IKNodeType.rAnkle]       = { tf = ikSolver.rightFootEffector.target,                 colliderTF = nil, ikJson = nil, localPlayTimes = 0 } -- 右-脚踝
    self.dragNodes[IKNodeType.rHip]         = { tf = ikSolver.rightThighEffector.target,                colliderTF = nil, ikJson = nil, localPlayTimes = 0 } -- 右-臀
    self.dragNodes[IKNodeType.rKnee]        = { tf = ikSolver.rightLegChain.bendConstraint.bendGoal,    colliderTF = nil, ikJson = nil, localPlayTimes = 0 } -- 右-膝盖

    
    -- 当前正在被 cam 看着的 dragNode; (最靠近 cam 射线的那个)
    self.gazedDragNodeItem = {
        dragNode = nil,
        gazedTime = 0.0, 
        gazedTimeThreshold = 0.0,
    }
    self.lastNearestDragNode = nil

    -- debug:
    print("----- ik tfs: ----")
    for enumKey,node in pairs(self.dragNodes) do 
        print("key:" ..tostring(enumKey)..";    go:"..tostring(node.tf.name))
    end 

    ---
    for enumKey,node in pairs(self.dragNodes) do
        node.collider = KTool.GetOrAddComponent( node.tf.gameObject, typeof(SphereCollider) )
        node.idComp = KTool.GetOrAddComponent( node.tf.gameObject, typeof(IDComp) )
        -- 
        node.collider.isTrigger = true
        node.collider.radius = 0.1
        node.idComp.id = ColliderIdType.IKDrag
        node.idComp.stringId = tostring(enumKey)
        node.collider.enabled = false
    end

    
    -- 记录 role 的初始 ik 参数; 当 ik 交互结束后, 可以回退到这个 init 参数;
    self.initIKGroup = IdolLive3D_IKGroup.New( self.fullBodyBipedIK )
    self.initIKGroup:CopyFromFullBodyBipedIK_All() 

    
    -- 正在操作的 ik 参数组:
    self.currentIKGroup = IdolLive3D_IKGroup.New( self.fullBodyBipedIK )
    self.currentIKGroup:CopyFrom_All( self.initIKGroup )

    -- currentIKGroup 运动向的 参数组:
    self.tgtIKGroup = IdolLive3D_IKGroup.New( self.fullBodyBipedIK )
    self.tgtIKGroup:CopyFrom_All( self.initIKGroup )

    ---
    local newgo = GameObject("ikRegionRoot")
    self.ikRegionRootTF = newgo.transform



    -- debug
    self.debugBallTF = nil
    if false then 
        self.debugBallTF = IdolLive3D_RoleIKMgr.CreateNewPrimitive( "_IK_DragBall_Debug_" )
        CfUtils.SetActive( self.debugBallTF, true )
    end
 
    --
    self.isInit = true
end



function IdolLive3D_RoleIKMgr:__delete()
    if isNotNull(self.ikRegionRootTF) then 
        Object.Destroy( self.ikRegionRootTF.gameObject )
    end 
    if isNotNull(self.debugBallTF) then 
        Object.Destroy( self.debugBallTF.gameObject )
    end 
end




