function IdolLive3D_RoleIKMgr:SelfUpdate()
    if self.isInit ~= true then 
        return
    end 
    if self.isFind_FullBodyBipedIK == false then 
        return
    end 
    if isNull(self.mainForRuntime.idolLive3D_InteractiveManagerEnv) then 
        return
    end 
    if self.interactiveManagerEnv == nil  then 
        self.interactiveManagerEnv = self.mainForRuntime.idolLive3D_InteractiveManagerEnv
    end

    -- ===========================================
    -- 即便 close enough 了, 也不会停止 lerp, 牺牲这点性能来保证一定出现时序异常; (否则会导致 _EndIKDraging() 中的异常)
    local w = 0.3
    if self.isUsed.Body then 
        IdolLive3D_IKGroup.Lerp_Body( self.currentIKGroup.Body, self.tgtIKGroup.Body, w )
        self.currentIKGroup:SetToFullBodyBipedIK_Body()
    end 
    if self.isUsed.LeftArm then 
        IdolLive3D_IKGroup.Lerp_Arm( self.currentIKGroup.LeftArm, self.tgtIKGroup.LeftArm, w )
        self.currentIKGroup:SetToFullBodyBipedIK_LeftArm()
    end 
    if self.isUsed.RightArm then 
        IdolLive3D_IKGroup.Lerp_Arm( self.currentIKGroup.RightArm, self.tgtIKGroup.RightArm, w )
        self.currentIKGroup:SetToFullBodyBipedIK_RightArm()
    end 
    if self.isUsed.LeftLeg then 
        IdolLive3D_IKGroup.Lerp_Leg( self.currentIKGroup.LeftLeg, self.tgtIKGroup.LeftLeg, w )
        self.currentIKGroup:SetToFullBodyBipedIK_LeftLeg()
    end 
    if self.isUsed.RightLeg then 
        IdolLive3D_IKGroup.Lerp_Leg( self.currentIKGroup.RightLeg, self.tgtIKGroup.RightLeg, w )
        self.currentIKGroup:SetToFullBodyBipedIK_RightLeg()
    end 

    ---
    if isNotNull(self.catchedDragNode) then 
        assert( isNotNull(self.IKParamJson) )

        if IdolLive3D_StatesV2.IsIKDragging == false then 
            self.catchedDragNode.colliderTF.position = Vector3.Lerp( self.catchedDragNode.colliderTF.position, self.catchedInfo.initColliderPos, self.IKParamJson.backToOriginLerpW )
        end 

        if isNotNull(self.debugBallTF) then 
            self.debugBallTF.position = self.catchedDragNode.colliderTF.position
        end
    end



    self:_UIIKHand_Update()
end



function IdolLive3D_RoleIKMgr:_Reset_GazedDragNodeItem()
    --printError("_Reset_GazedDragNodeItem")
    self.gazedDragNodeItem.dragNode = nil
    self.gazedDragNodeItem.gazedTime = 0.0    
end



-- ============================ ui ===================================


function IdolLive3D_RoleIKMgr:_UIIKHand_Update()
    if isNull(self.IKParamJsonList) or table.count(self.IKParamJsonList) == 0 then 
        return
    end 
    
    -- ===================================================
    -- 隐藏 ui:
    if  IdolLive3D_StatesV2.IsInsideIKDragSwipe == true  or     -- 玩家开始 ik swipe 操作
        self.interactiveManagerEnv:IsInIdleState() ~= true      -- 不在 Idle state 
    then 
        if self.ikHandEnv.isShow == true then 
            self:_Reset_GazedDragNodeItem()
            self.ikHandEnv:SetShow(false)
        end 
        return
    end 

    -- ====== 
    local screenMidPosOS = Vector3( SCREEN_WIDTH*0.5, SCREEN_HEIGHT*0.5, 0 )

    -- 找出离视线最近的 dragNode:
    local nearestDragNodeItems = { dis = 99999999, dragNode = nil, posOS = nil }
    for _,ikJson in pairs(self.IKParamJsonList) do 
        local _dragNode = self.dragNodes[ikJson.ikNodeType]
        local posOS = self.mainCamera:WorldToScreenPoint(_dragNode.tf.position)
        posOS.z = 0.0
        local dis = (posOS-screenMidPosOS).magnitude
        if dis < nearestDragNodeItems.dis then 
            nearestDragNodeItems.dis = dis
            nearestDragNodeItems.dragNode = _dragNode
            nearestDragNodeItems.posOS = posOS
        end 
    end

    -- 筛除掉屏幕之外的 dragNode:
    if isNotNull(nearestDragNodeItems.dragNode) then 
        local posOS = nearestDragNodeItems.posOS
        if  (Mathf.Abs(posOS.x-screenMidPosOS.x) < SCREEN_WIDTH  * 0.5 * 0.9) and 
            (Mathf.Abs(posOS.y-screenMidPosOS.y) < SCREEN_HEIGHT * 0.5 * 0.9)
        then 
            -- 此点进入 可展示区了
        else 
            nearestDragNodeItems.dragNode = nil
        end 
    end 
    

    if nearestDragNodeItems.dragNode == nil then  
        if self.ikHandEnv.isShow == true then 
            self:_Reset_GazedDragNodeItem()
            self.ikHandEnv:SetShow(false)
        end
        return
    end 

    -- ===========
    local nearestDragNode = nearestDragNodeItems.dragNode
    --print("node = " .. tostring(nearestDragNode.ikJson.key))

    local isChange = nearestDragNode ~= self.lastNearestDragNode
    self.lastNearestDragNode = nearestDragNode
    --print("isChange - " .. tostring(isChange) )


    -- 触发次数越多, 待机时长越长:
    local _gazedTimeThreshold = (nearestDragNode.ikJson.totalPlayTimes == 0 and 0.5 or 1.0) + 
                                nearestDragNode.localPlayTimes * 1 

    if nearestDragNode ~= self.gazedDragNodeItem.dragNode then         
        -- 更换:
        self.gazedDragNodeItem = {
            dragNode = nearestDragNode,
            gazedTime = 0.0, 
            gazedTimeThreshold = _gazedTimeThreshold
        }
    end 

    if isNull(self.gazedDragNodeItem.dragNode) then 
        printError(" 异常, 请检查代码 ")
        return
    end 

    self.gazedDragNodeItem.gazedTime = self.gazedDragNodeItem.gazedTime + Time.deltaTime

    if isChange then 
        self.ikHandEnv:SetShow(false)
    end 

    if (self.ikHandEnv.isShow == false and self.gazedDragNodeItem.gazedTime > self.gazedDragNodeItem.gazedTimeThreshold ) then 
        --printError("执行 show, total = " .. tostring(self.gazedDragNodeItem.gazedTimeThreshold) )
        --- 切换需要显示的 dragNode:
        local uiParams = self.gazedDragNodeItem.dragNode.ikJson.uiParams
        self.ikHandEnv:SetParmas(   self.gazedDragNodeItem.dragNode.tf, uiParams.handMoveMode, uiParams.handSwingDirDegree, 
                                    uiParams.handSwingWeight * SCREEN_HEIGHT, uiParams.handSwingCurvature, uiParams.movePeriod )
        self.ikHandEnv:SetShow(true)
    end 
    
end





