-- 当进入一个新的 stage, 或 superTimeline clip 中时:
function IdolLive3D_RoleIKMgr:IntoNewState( IKParamsJson_ )
    if self.isInit ~= true then 
        return
    end 
    --printError("IntoNewState")

    self.IKParamJsonList = IKParamsJson_

    self.catchedDragNode = nil
    self:_Reset_GazedDragNodeItem()
    self.ikHandEnv:SetShow(false)

    -- 先把所有 dragNode collider 关闭:
    for enumKey,dragNode in pairs(self.dragNodes) do
        dragNode.collider.enabled = false
        dragNode.ikJson = nil
        dragNode.localPlayTimes = 0
    end 
    -- 把几个指定 ik dragNode 开启, 设置其半径:
    for _,ikJson in pairs(self.IKParamJsonList) do 
        local dragNode = self.dragNodes[ikJson.ikNodeType]
        assert( isNotNull(dragNode) )
        dragNode.collider.radius = checkNumber( Mathf.Max(ikJson.colliderRadius, 0) )
        dragNode.collider.enabled = true
        dragNode.ikJson = ikJson
        dragNode.localPlayTimes = 0
    end
    ---
    local isHaveIK = (#self.IKParamJsonList > 0)
    if isHaveIK then 
        self.fullBodyBipedIK.enabled = true
    else 
        self.fullBodyBipedIK.enabled = false
    end 
end


