function IdolLive3D_RoleIKMgr:BindInput( inputEnv_ )
    inputEnv_:Add_OnSwipeStartCallBack( function(gesture_)
        self:_OnSwipeStartCallBack(gesture_)
    end )
    inputEnv_:Add_OnSwipeCallBack( function(gesture_)
        self:_OnSwipeCallBack(gesture_)
    end )
    inputEnv_:Add_OnSwipeEndCallBack( function(gesture_)
        self:_OnSwipeEndCallBack(gesture_)
    end )
end




function IdolLive3D_RoleIKMgr:_IsStateTypeCanTriggerIK( stateType_ )
    return  stateType_ == IdolLive3D_States.InteractiveStateType.Idle or 
            stateType_ == IdolLive3D_States.InteractiveStateType.SuperTimeline
end



function IdolLive3D_RoleIKMgr:_OnSwipeStartCallBack( gesture_ )
    if self.isInit ~= true then
        return
    end

    local lastIState = self.interactiveManagerEnv:PeekLastInteractiveStateFromQueue().iState
    print( "tap - ik; lastState name: ".. tostring(lastIState.iStateName) ..", stateType: " .. IdolLive3D_States.GetStateTypeString(lastIState.stateType) )

    if self:_IsStateTypeCanTriggerIK(lastIState.stateType) == false then 
        print("当前 iState 无法触发 ik;")
        return
    end     

    local tapPos2 = gesture_.startPosition
    local tapPos3 = Vector3( tapPos2.x, tapPos2.y, 0.0 )
    local ray = self.mainCamera:ScreenPointToRay(tapPos3) -- Ray
    ---
    local legalHitInfos = {} -- 所有携带了 ID组件的 trigger 碰撞体信息
    local raycastHits, raycastHitsNum = IdolLive3D_Utils.RaycastNonAlloc( ray.origin, ray.direction, 20.0, IdolLive3D_StatesV2.collideLayerMask, QueryTriggerInteraction.Collide )
    for i=0, raycastHitsNum-1 do 
        local hit = raycastHits[i]
        if isNotNull(hit) and isNotNull( hit.collider) then
            local idComp = KTool.GetComponent(hit.collider.gameObject, typeof(IDComp))
            if  isNotNull(idComp) and
                idComp.id == ColliderIdType.IKDrag and -- 过滤掉其它的类型
                type(idComp.stringId) == "string" and (#idComp.stringId > 0) 
            then 
                table.insert( legalHitInfos, {distance = hit.distance, idStr = idComp.stringId, collider = hit.collider} )
            end
        end
    end
    ---
    if #legalHitInfos == 0 then 
        return
    end 
    -- 距离由近及远
    table.sort(legalHitInfos, function(a, b)
        return checkNumber(a.distance) < checkNumber(b.distance)
    end)

    local nearestHitInfo = legalHitInfos[1]
    if string.isEmpty(nearestHitInfo.idStr) or tonumber(nearestHitInfo.idStr) == nil then 
        return
    end

    -- !!! ======================== 正式点中 drag collider: ==================================
    print("点到 IK Node: " .. tostring(nearestHitInfo.idStr))

    IdolLive3D_StatesV2.IsInsideIKDragSwipe = true
    IdolLive3D_StatesV2.IsIKDragging = true
    local dragNodeInt = tonumber(nearestHitInfo.idStr) -- 属于 IKNodeType 
    self.catchedDragNode = self.dragNodes[dragNodeInt]
    assert( isNotNull(self.catchedDragNode) )
    self.catchedDragNode.colliderTF = nearestHitInfo.collider.transform
    ---
    self.IKParamJson = nil
    for _,ikJson in pairs(self.IKParamJsonList) do 
        if ikJson.ikNodeType == dragNodeInt then 
            self.IKParamJson = ikJson
        end 
    end 
    assert( isNotNull(self.IKParamJson) )
    ---  
    self.catchedDragNode.localPlayTimes = self.catchedDragNode.localPlayTimes + 1 -- 立刻记录
    self.IKParamJson.totalPlayTimes = self.IKParamJson.totalPlayTimes + 1

    ---
    local ikRegionJson = self.IKParamJson.ikRegionJson
    IdolLive3D_UtilsV2.SyncTransform( self.ikRegionRootTF, ikRegionJson.posWS, ikRegionJson.rotationWS )

    self.catchedInfo = 
    {
        colliderDistance = (self.catchedDragNode.colliderTF.position - self.mainCamera.transform.position).magnitude,
        initColliderPos = self.catchedDragNode.colliderTF.position,
        lastDragPosWS = nil,
    }

    -- IKGroup参数:
    local ikGroupJson = self.IKParamJson.ikGroup
    self.isUsed = 
    {
        Body        = (ikGroupJson.Body.isUsed==true),
        LeftArm     = (ikGroupJson.LeftArm.isUsed==true),
        RightArm    = (ikGroupJson.RightArm.isUsed==true),
        LeftLeg     = (ikGroupJson.LeftLeg.isUsed==true),
        RightLeg    = (ikGroupJson.RightLeg.isUsed==true),
    }
    ---
    if self.isUsed.Body then 
        IdolLive3D_IKGroup.CopyFromJson_Body( ikGroupJson.Body, self.tgtIKGroup.Body )
    end 
    if self.isUsed.LeftArm then 
        IdolLive3D_IKGroup.CopyFromJson_Arm( ikGroupJson.LeftArm, self.tgtIKGroup.LeftArm )
    end 
    if self.isUsed.RightArm then 
        IdolLive3D_IKGroup.CopyFromJson_Arm( ikGroupJson.RightArm, self.tgtIKGroup.RightArm )
    end 
    if self.isUsed.LeftLeg then 
        IdolLive3D_IKGroup.CopyFromJson_Leg( ikGroupJson.LeftLeg, self.tgtIKGroup.LeftLeg )
    end 
    if self.isUsed.RightLeg then 
        IdolLive3D_IKGroup.CopyFromJson_Leg( ikGroupJson.RightLeg, self.tgtIKGroup.RightLeg )
    end 
    
end





function IdolLive3D_RoleIKMgr:_OnSwipeCallBack( gesture_ )
    if self.isInit ~= true then
        return
    end
    if self.IKParamJson == nil then 
        return
    end     
    if IdolLive3D_StatesV2.IsInsideIKDragSwipe ~= true then 
        return
    end 
    if IdolLive3D_StatesV2.IsIKDragging ~= true then 
        return
    end 

    local tapPos2 = gesture_.position
    local tapPos3 = Vector3( tapPos2.x, tapPos2.y, 0.0 )
    local ray = self.mainCamera:ScreenPointToRay(tapPos3) -- Ray

    local ikRegionJson = self.IKParamJson.ikRegionJson

    if self.IKParamJson.iKRegionType == IdolLive3D_StatesV2.IKRegionType.Ellipse then 

        -- closestPosWS   -- ray 在交互运动区域内的 最近的点
        local closestPosWS, isInsideEllipse = IdolLive3D_UtilsV2.FindClosestPosOnEllipse( self.ikRegionRootTF, ray, ikRegionJson.radiusX, ikRegionJson.radiusZ )
        if isNull(closestPosWS) then 
            self:_EndIKDraging(gesture_) -- 终止 IKDrag;  -- !!! 多半是因为 鼠标离开窗口了
            return
        end 

        self.catchedInfo.lastDragPosWS = closestPosWS
        self.catchedDragNode.colliderTF.position = Vector3.Lerp( self.catchedDragNode.colliderTF.position, self.catchedInfo.lastDragPosWS, self.IKParamJson.dragLerpW )
        
        -- 自动脱钩:
        if  (self.IKParamJson.isAutoBackToOrigin == true) and  -- 开启 "脱钩"
            (self.catchedDragNode.colliderTF.position-closestPosWS).magnitude < self.IKParamJson.BackToOriginMinThreshold and -- 已经运动到目的点
            isInsideEllipse == false    -- 目标点超出椭圆了
        then 
            --printError("脱钩")
            self:_EndIKDraging(gesture_) -- 终止 IKDrag;
            return
        end 

    elseif self.IKParamJson.iKRegionType == IdolLive3D_StatesV2.IKRegionType.Arc then

        local closestPosWS, isInsideArc = IdolLive3D_UtilsV2.FindClosestPosOnArc( self.ikRegionRootTF, ray, ikRegionJson.radiusX, ikRegionJson.radiusZ, ikRegionJson.aPosLS, ikRegionJson.bPosLS )
        if isNull(closestPosWS) then 
            self:_EndIKDraging(gesture_) -- 终止 IKDrag;  -- !!! 多半是因为 鼠标离开窗口了
            return
        end 

        if isInsideArc == true then 
            self.catchedInfo.lastDragPosWS = closestPosWS
        end 
        if isNotNull(self.catchedInfo.lastDragPosWS) then 
            self.catchedDragNode.colliderTF.position = Vector3.Lerp( self.catchedDragNode.colliderTF.position, self.catchedInfo.lastDragPosWS, self.IKParamJson.dragLerpW )
        end

        -- 自动脱钩:
        if  (self.IKParamJson.isAutoBackToOrigin == true) and  -- 开启 "脱钩"
            isNotNull(self.catchedInfo.lastDragPosWS) and
            isInsideArc == false and
            (self.catchedDragNode.colliderTF.position-self.catchedInfo.lastDragPosWS).magnitude < self.IKParamJson.BackToOriginMinThreshold -- 已经运动到目的点
        then 
            --printError("脱钩")
            self:_EndIKDraging(gesture_) -- 终止 IKDrag;
            return
        end 
    
    else 
        printError("类型 异常: " .. tostring(self.IKParamJson.iKRegionType))
        return
    end

    -- 检查是否撞到了 动作触发区间:
    for _,iNode in pairs(ikRegionJson.interactRegionNodes) do 
        if (self.catchedDragNode.colliderTF.position-iNode.posWS).magnitude < iNode.radius then 
            --printError("hit 动作区域")
            Events.Broadcast(IdolLive3D_States.EventVirtualSimpleTap, iNode.key )
            self:_EndIKDraging(gesture_) -- 终止 IKDrag;
            break
        end 
    end 

    --printError("-- on")
end



function IdolLive3D_RoleIKMgr:_OnSwipeEndCallBack( gesture_ ) 
    if self.isInit ~= true then
        return
    end
    if self.IKParamJson == nil then 
        return
    end   
    if IdolLive3D_StatesV2.IsInsideIKDragSwipe ~= true then 
        return
    end 

    self:_EndIKDraging(gesture_)
    --printError("-- End")
    ---
    IdolLive3D_StatesV2.IsInsideIKDragSwipe = false
end



function IdolLive3D_RoleIKMgr:_EndIKDraging( gesture_ ) 
    --self.catchedDragNode = nil

    if self.isUsed.Body then 
        IdolLive3D_IKGroup.Copy_Body( self.initIKGroup.Body, self.tgtIKGroup.Body )
    end 
    if self.isUsed.LeftArm then 
        IdolLive3D_IKGroup.Copy_Arm( self.initIKGroup.LeftArm, self.tgtIKGroup.LeftArm )
    end 
    if self.isUsed.RightArm then 
        IdolLive3D_IKGroup.Copy_Arm( self.initIKGroup.RightArm, self.tgtIKGroup.RightArm )
    end 
    if self.isUsed.LeftLeg then 
        IdolLive3D_IKGroup.Copy_Leg( self.initIKGroup.LeftLeg, self.tgtIKGroup.LeftLeg )
    end 
    if self.isUsed.RightLeg then 
        IdolLive3D_IKGroup.Copy_Leg( self.initIKGroup.RightLeg, self.tgtIKGroup.RightLeg )
    end 
    ---
    IdolLive3D_StatesV2.IsIKDragging = false
end






function IdolLive3D_RoleIKMgr:_IsUsedAllFalse()
    return self.isUsed.Body==false and self.isUsed.LeftArm==false and self.isUsed.RightArm==false and self.isUsed.LeftLeg==false and self.isUsed.RightLeg==false
end







-- =============================== debug ===============================

-- 新建个 杆子 / 球
function IdolLive3D_RoleIKMgr.CreateNewPrimitive( name_ )

    local PrimitiveType = CS.UnityEngine.PrimitiveType

    local newgo = GameObject.CreatePrimitive(PrimitiveType.Sphere)
    local newTF = newgo.transform
    newgo.name = name_

    local renderer = newgo:GetComponent("Renderer")
    if renderer and renderer.material then -- 因为是 debug 工具. 无需考虑这个 material 的释放问题
        renderer.material:SetColor("_BaseColor", Color.red)
    end

    local collider = KTool.GetComponent(newgo, typeof(Collider))
    Object.Destroy( collider )
    newTF.localScale = Vector3( 0.1, 0.1, 0.1 )
    newTF.position = Vector3(999,999,999)
    return newTF
end





return IdolLive3D_RoleIKMgr
